me(@Req() req: { user: User & { timezone: string } }): ProfileResponseDto {
  const u = req.user;
  return {
    id: u.id,
    displayName: `${u.firstName} ${u.lastName}`,
    email: u.email,
    timezone: u.timezone,
  };
}

